INSERT INTO repair_guides
    (title, slug, category_slug, device_type, summary, symptoms, possible_causes, steps_json, do_not, when_to_contact, status, published_at)
VALUES
    ('Ноутбук не включается', 'laptop-wont-start', 'laptops-pc', 'Ноутбук', 'Что проверить, если ноутбук не реагирует на кнопку питания или сразу выключается.', 'Нет изображения и индикаторов; индикатор питания мигает; ноутбук включается на секунду и выключается.', 'Разряженная батарея, неисправный адаптер питания, повреждённый кабель или аппаратная неисправность.', JSON_ARRAY('Отключите от ноутбука флешки, внешние диски, док-станцию и другие аксессуары.', 'Проверьте, плотно ли подключён штатный адаптер к розетке и ноутбуку. Осмотрите кабель на видимые повреждения.', 'Попробуйте другую исправную розетку, не используя сомнительные переходники.', 'Оставьте устройство подключённым к штатному адаптеру на 20–30 минут, затем однократно попробуйте включить.', 'Запишите, какие индикаторы загораются и слышны ли звуки при нажатии кнопки питания.'), 'Не разбирайте корпус и не вскрывайте адаптер питания. Не подключайте повреждённый кабель и не пытайтесь замыкать контакты.', 'Обратитесь к мастеру, если ноутбук не реагирует после проверки питания, пахнет гарью, сильно нагревается или имеет следы жидкости.', 'published', CURRENT_TIMESTAMP),
    ('Ноутбук перегревается', 'laptop-overheating', 'laptops-pc', 'Ноутбук', 'Безопасные действия при сильном нагреве, шуме вентиляторов и внезапных выключениях.', 'Корпус горячий; вентилятор постоянно шумит; производительность падает; ноутбук выключается под нагрузкой.', 'Перекрытые вентиляционные отверстия, высокая нагрузка, пыль внутри корпуса или неисправность системы охлаждения.', JSON_ARRAY('Поставьте ноутбук на твёрдую ровную поверхность, не на одеяло или мягкую мебель.', 'Убедитесь, что вентиляционные отверстия снаружи не закрыты предметами.', 'Закройте тяжёлые приложения и проверьте, уменьшается ли нагрев в режиме простоя.', 'Перезагрузите устройство и проверьте, не повторяется ли перегрев при обычной работе.', 'Сохраните важные файлы, если устройство выключается самостоятельно.'), 'Не продолжайте работу при запахе гари, деформации корпуса или вздутии батареи. Не вставляйте предметы в вентиляционные отверстия и не вскрывайте систему охлаждения.', 'Обратитесь к мастеру, если перегрев повторяется, вентилятор не вращается, ноутбук выключается или аккумулятор выглядит деформированным.', 'published', CURRENT_TIMESTAMP),
    ('Вентилятор ноутбука сильно шумит', 'laptop-fan-noise', 'laptops-pc', 'Ноутбук', 'Как отличить обычный шум охлаждения от признаков неисправности вентилятора.', 'Постоянный гул, треск, скрежет или резкое увеличение оборотов вентилятора.', 'Высокая нагрузка, пыль в системе охлаждения, износ вентилятора или нарушение его крепления.', JSON_ARRAY('Проверьте, не запущены ли игры, обновления или ресурсоёмкие программы.', 'Закройте ненужные приложения и подождите несколько минут.', 'Поставьте устройство на ровную поверхность и проверьте, не перекрыты ли воздухозаборники.', 'Запишите, появляется ли шум сразу после включения или только под нагрузкой.', 'Сделайте резервную копию важных данных, если шум сопровождается зависаниями или выключениями.'), 'Не пытайтесь смазывать вентилятор через отверстия и не продувайте ноутбук компрессором. Не продолжайте работу при скрежете или запахе гари.', 'Обратитесь к мастеру, если слышен механический скрежет, вибрация, вентилятор перестал работать или температура быстро растёт.', 'published', CURRENT_TIMESTAMP),
    ('Ноутбук работает очень медленно', 'laptop-running-slow', 'laptops-pc', 'Ноутбук', 'Проверки, которые помогут найти очевидные причины медленной работы без разборки устройства.', 'Долго загружается система; программы открываются медленно; интерфейс зависает.', 'Перегруженная автозагрузка, недостаток свободного места, фоновые обновления, вредоносное ПО или неисправность накопителя.', JSON_ARRAY('Перезагрузите ноутбук и проверьте, повторяется ли проблема.', 'Откройте диспетчер задач и посмотрите, не загружает ли одна программа процессор, память или диск постоянно.', 'Проверьте свободное место на системном диске. Не удаляйте незнакомые системные файлы.', 'Отключите из автозагрузки только те приложения, назначение которых вам известно.', 'Запустите проверку штатным защитником системы и дождитесь завершения обновлений.'), 'Не устанавливайте случайные «ускорители» и чистильщики реестра. Не удаляйте системные папки и не форматируйте накопитель.', 'Обратитесь к мастеру, если диск исчезает, появляются ошибки чтения, синий экран или зависания продолжаются после базовых проверок.', 'published', CURRENT_TIMESTAMP),
    ('Смартфон не заряжается', 'phone-not-charging', 'smartphones', 'Смартфон', 'Что безопасно проверить, если телефон не показывает зарядку или заряжается с перебоями.', 'Нет значка зарядки; заряд появляется только при определённом положении кабеля; зарядка прерывается.', 'Неисправный кабель или адаптер, загрязнение разъёма, повреждение порта или батареи.', JSON_ARRAY('Попробуйте другой заведомо исправный кабель и совместимый адаптер питания.', 'Подключите зарядное устройство к другой исправной розетке.', 'Осмотрите разъём при хорошем освещении, не вставляя в него инструменты.', 'Перезагрузите смартфон и проверьте наличие системного уведомления о влаге или температуре.', 'Оставьте телефон на зарядке на 15–20 минут только при отсутствии нагрева и других опасных признаков.'), 'Не чистите разъём иголкой, скрепкой или металлическими предметами. Не используйте повреждённый кабель. Не заряжайте устройство при вздутии батареи или попадании жидкости.', 'Немедленно прекратите зарядку при сильном нагреве, запахе, вздутии или следах жидкости. В остальных случаях обратитесь к мастеру, если исправные аксессуары не помогают.', 'published', CURRENT_TIMESTAMP),
    ('Смартфон быстро разряжается', 'phone-battery-drains-fast', 'smartphones', 'Смартфон', 'Проверьте программные причины повышенного расхода батареи и признаки её физического повреждения.', 'Заряд быстро падает в режиме ожидания; телефон нагревается; процент заряда меняется скачками.', 'Высокая яркость, активные фоновые приложения, слабый сигнал сети, обновления или износ батареи.', JSON_ARRAY('Откройте настройки батареи и посмотрите, какие приложения расходуют больше всего энергии.', 'Уменьшите яркость экрана и временно отключите ненужные фоновые функции.', 'Проверьте, не устанавливаются ли обновления и не выполняется ли резервное копирование.', 'Перезагрузите смартфон и понаблюдайте за расходом заряда в обычном режиме.', 'Запишите примерное время работы и условия, при которых заряд уходит быстрее всего.'), 'Не вскрывайте корпус и не пытайтесь самостоятельно извлечь встроенную батарею. Не охлаждайте горячий телефон в холодильнике.', 'Прекратите использование и зарядку при вздутии корпуса, запахе или чрезмерном нагреве. При резком падении заряда обратитесь к мастеру для диагностики батареи.', 'published', CURRENT_TIMESTAMP),
    ('Компьютер включается, но нет изображения', 'pc-no-display', 'laptops-pc', 'Настольный компьютер', 'Проверки монитора, кабелей и выбранного входа до обращения в сервис.', 'Компьютер шумит и светится, но экран остаётся чёрным; монитор показывает «Нет сигнала».', 'Неверный источник сигнала, неплотно подключённый кабель, неисправность монитора или аппаратная проблема компьютера.', JSON_ARRAY('Убедитесь, что монитор включён и на нём выбран правильный вход HDMI, DisplayPort или другой используемый порт.', 'Проверьте, плотно ли подключён видеокабель с обеих сторон.', 'При наличии другого исправного кабеля попробуйте заменить кабель.', 'Проверьте, показывает ли монитор меню настроек без подключения к компьютеру.', 'Отключите внешние USB-устройства и выполните один обычный перезапуск.'), 'Не открывайте блок питания и не касайтесь внутренних компонентов при подключённом кабеле питания. Не переставляйте комплектующие без подготовки.', 'Обратитесь к мастеру, если монитор исправен, кабель проверен, но сигнала нет, либо компьютер издаёт необычные звуки или самопроизвольно выключается.', 'published', CURRENT_TIMESTAMP),
    ('Wi-Fi часто отключается', 'wifi-keeps-disconnecting', 'network', 'Роутер и сеть Wi-Fi', 'Проверьте домашнюю сеть и отделите проблему роутера от проблемы отдельного устройства.', 'Соединение пропадает; скорость резко падает; одно устройство отключается чаще остальных.', 'Сбой роутера, слабый сигнал, помехи, проблема провайдера или настройки устройства.', JSON_ARRAY('Проверьте, отключается ли Wi-Fi на нескольких устройствах или только на одном.', 'Подойдите ближе к роутеру и проверьте, становится ли соединение стабильнее.', 'Посмотрите, горят ли индикаторы питания и интернет-соединения на роутере.', 'Перезапустите роутер обычным способом и дождитесь восстановления соединения.', 'Проверьте сообщения провайдера о плановых работах или аварии.'), 'Не нажимайте кнопку Reset и не сбрасывайте настройки роутера без сохранённых параметров подключения. Не публикуйте пароль Wi-Fi.', 'Обратитесь к провайдеру, если интернет отсутствует на всех устройствах. Обратитесь к мастеру, если сбои связаны только с одним устройством или повторяются после проверки сети.', 'published', CURRENT_TIMESTAMP),
    ('Внешний диск не определяется', 'external-drive-not-detected', 'storage', 'Внешний HDD или SSD', 'Безопасные действия, если внешний накопитель не появился в проводнике.', 'Диск не отображается; система предлагает форматирование; устройство периодически отключается.', 'Неисправный кабель или порт, недостаток питания, ошибка файловой системы или поломка накопителя.', JSON_ARRAY('Попробуйте другой USB-порт без переходника и другой исправный кабель, если он есть.', 'Проверьте, появляется ли звук подключения или уведомление системы.', 'Откройте системное управление дисками только для просмотра и проверьте, виден ли накопитель там.', 'Запишите точный текст системного сообщения и не выполняйте предложенные операции.', 'Отключите накопитель, если слышны щелчки, скрежет или он сильно нагревается.'), 'Не нажимайте «Форматировать», «Инициализировать» или «Создать раздел». Не запускайте восстановление на исходный диск, если данные важны.', 'Если на диске есть важные файлы, при любых ошибках чтения прекратите эксперименты и обратитесь к специалисту по восстановлению данных.', 'published', CURRENT_TIMESTAMP),
    ('На диске почти не осталось места', 'storage-running-out-of-space', 'storage', 'SSD или HDD', 'Как освободить место без риска удалить документы или системные файлы.', 'Появляется уведомление о нехватке места; обновления не устанавливаются; программы не сохраняют файлы.', 'Большие видео и архивы, корзина, временные файлы или резервные копии.', JSON_ARRAY('Откройте параметры хранилища и посмотрите, какие категории занимают больше всего места.', 'Проверьте папку загрузок и удаляйте только те файлы, которые точно больше не нужны.', 'Очистите корзину после проверки её содержимого.', 'Используйте штатный инструмент очистки временных файлов операционной системы.', 'Перенесите личные фотографии и видео на проверенный резервный носитель, затем убедитесь, что копия открывается.'), 'Не удаляйте папки Windows, Program Files, системные разделы и незнакомые файлы. Не используйте случайные программы для очистки.', 'Обратитесь к мастеру, если свободное место быстро исчезает снова, накопитель выдаёт ошибки или важные файлы пропали.', 'published', CURRENT_TIMESTAMP),
    ('Операционная система не загружается', 'operating-system-wont-boot', 'software', 'Компьютер или ноутбук', 'Что записать и проверить, если система застревает на логотипе или показывает ошибку загрузки.', 'Загрузка циклически перезапускается; появляется экран восстановления; система зависает на логотипе.', 'Сбой обновления, повреждение системных файлов, проблемы накопителя или подключённое внешнее устройство.', JSON_ARRAY('Сфотографируйте экран с точным текстом ошибки или кодом.', 'Отключите флешки, внешние диски и другие необязательные устройства.', 'Выполните один обычный перезапуск.', 'Если открылось штатное меню восстановления, запишите доступные варианты и не запускайте сброс без понимания последствий.', 'Уточните, есть ли на устройстве важные файлы без резервной копии.'), 'Не переустанавливайте систему и не форматируйте диск до оценки сохранности данных. Не меняйте случайные параметры BIOS/UEFI.', 'Обратитесь к мастеру, если система повторно не загружается, диск исчезает или требуется сохранить важные данные.', 'published', CURRENT_TIMESTAMP),
    ('Клавиатура или мышь не работают', 'keyboard-mouse-not-working', 'peripherals', 'Клавиатура или мышь', 'Простые проверки подключения, питания и совместимости периферии.', 'Устройство не реагирует; часть клавиш не работает; курсор не двигается.', 'Разряженная батарея, неисправный кабель, USB-порт, беспроводной приёмник или программный сбой.', JSON_ARRAY('Для проводного устройства проверьте кабель и подключите его к другому USB-порту.', 'Для беспроводного устройства проверьте батарейки или заряд и включён ли переключатель питания.', 'Подключите устройство напрямую, без USB-хаба.', 'Проверьте клавиатуру или мышь на другом совместимом компьютере, если это возможно.', 'Перезагрузите компьютер и проверьте, работает ли устройство на экране входа.'), 'Не разбирайте устройство при подключённом питании и не устанавливайте неизвестные драйверы с непроверенных сайтов.', 'Обратитесь к мастеру, если несколько исправных устройств не работают в одном компьютере или USB-порты имеют видимые повреждения.', 'published', CURRENT_TIMESTAMP)
